"active_horizon_records":[{"id":"HOR-010","title":"Immigration-courthouse arrests and courthouse-access chilling","issue_url":"https://github.com/Thorncrag/ARRP/issues/15","workflow_status":"Deferred","horizon_history":{"original_concern":"Immigration-courthouse arrests and the risk that enforcement activity deters participation in immigration or other judicial proceedings."}},{"id":"HOR-023","title":"Foreign Election Interference and Campaign Counterintelligence Safeguards","issue_url":"https://github.com/Thorncrag/ARRP/issues/234","workflow_status":"Deferred","horizon_history":{"original_concern":"Foreign election interference and campaign counterintelligence safeguards arising from the Mueller Report foreign-interference record and related Durham/FISA process source-development questions."}},{"id":"HOR-026","title":"Presidential Withdrawal or Constructive Withdrawal from International Commitments","issue_url":"https://github.com/Thorncrag/ARRP/issues/245","workflow_status":"Development","horizon_history":{"original_concern":"Presidential formal or constructive withdrawal from congressionally or Senate-approved international organizations, alliances, treaty commitments, and comparable international institutions through withdrawal notices, participation suspension, deliberate arrears, representative vacancies, or circumvention of statutory safeguards."}},{"id":"HOR-027","title":"Presidential Policymaking Through Privately Controlled Social Media","issue_url":"https://github.com/Thorncrag/ARRP/issues/247","workflow_status":"Development","horizon_history":{"original_concern":"A President may use a personal or privately controlled social-media account as the initial or exclusive channel for major policy decisions, directives, foreign-policy positions, or other consequential official announcements."}},{"id":"HOR-029","title":"Presidential Self-Dealing Through an Officially Favored Private Platform","issue_url":"https://github.com/Thorncrag/ARRP/issues/249","workflow_status":"Development","horizon_history":{"original_concern":"Presidential use of an officially favored communications platform in which the President retains a substantial beneficial financial interest may allow a president-beneficial company to monetize official conduct and information."}},{"id":"HOR-031","title":"Durability and Revocation of National Monument Protections","issue_url":"https://github.com/Thorncrag/ARRP/issues/251","workflow_status":"Blocked","horizon_history":{"original_concern":"An already-established national monument may lack durable protection if a successor President can unilaterally abolish it or materially diminish its protected boundary."}},{"id":"HOR-033","title":"Enforceability of Accessibility Duties for Presidential Communications","issue_url":"https://github.com/Thorncrag/ARRP/issues/253","workflow_status":"Development","horizon_history":{"original_concern":"Existing accessibility duties for presidential and White House communications may lack a sufficiently explicit private enforcement route or sufficiently timely remedy."}},{"id":"HOR-035","title":"Executive Review Evasion Through Withdrawal, Replacement, Settlement, or Mootness","issue_url":"https://github.com/Thorncrag/ARRP/issues/255","workflow_status":"Research","horizon_history":{"original_concern":"Executive defendants may withdraw, replace, narrow, settle, or temporarily cease challenged conduct after harm occurs and thereby avoid a durable merits ruling without repairing the underlying authority or process weakness."}},{"id":"HOR-037","title":"Immigration Detention, Removal Process, and Access Safeguards","issue_url":"https://github.com/Thorncrag/ARRP/issues/257","workflow_status":"Research","horizon_history":{"original_concern":"Civil immigration detention, transfer, or removal may be completed or materially advanced before meaningful judicial review can occur, making a later legal victory incapable of fully repairing the harm."}},{"id":"HOR-038","title":"Endangered Species Act Regulatory-Boundary Monitoring","issue_url":"https://github.com/Thorncrag/ARRP/issues/274","workflow_status":"Deferred","horizon_history":{"original_concern":"Finalized 2026 regulations under ESA sections 4(d) and 4(b)(2) may reveal a statutory-boundary or timely-remedy weakness if delegated discretion displaces congressionally prescribed decision criteria or causes difficult-to-repair loss before review."}},{"id":"HOR-039","title":"Functional Accessibility of Existing Lawful Immigration and Residency Pathways","issue_url":"https://github.com/Thorncrag/ARRP/issues/300","workflow_status":"Development","horizon_history":{"original_concern":"Lawful immigration and residency pathways created by Congress may become functionally inaccessible when statutory eligibility is not matched by adequate processing capacity, transparent queue administration, reasonable timelines, status-continuity protections, consistent standards, records access, or meaningful review."}},{"id":"HOR-040","title":"Safeguards for Broad Presidential Tariff Delegations","issue_url":"https://github.com/Thorncrag/ARRP/issues/302","workflow_status":"Development","horizon_history":{"original_concern":"Economically consequential tariffs may be imposed, escalated, negotiated, or selectively waived under several broad trade-statute delegations without contemporaneous legislative approval or uniform safeguards."}},{"id":"HOR-041","title":"Safeguards for Class-Based Presidential Entry Suspensions","issue_url":"https://github.com/Thorncrag/ARRP/issues/303","workflow_status":"Development","horizon_history":{"original_concern":"INA section 212(f) may permit broad class-based entry suspensions through generalized detrimental-interest findings without a sufficiently specific statutory nexus, fixed duration, transparent record, or timely review."}},{"id":"HOR-042","title":"Minimum Safeguards for Presidential Statutory Waivers","issue_url":"https://github.com/Thorncrag/ARRP/issues/304","workflow_status":"Development","horizon_history":{"original_concern":"Statutes may authorize a President to suspend enacted substantive or procedural safeguards through broad findings without consistent minimum requirements for reasons, scope, duration, notice, reporting, or review."}},{"id":"HOR-043","title":"Presidential Recognition of International Bodies With Domestic Legal Privileges","issue_url":"https://github.com/Thorncrag/ARRP/issues/305","workflow_status":"Development","horizon_history":{"original_concern":"Existing law may permit a President to recognize an international body, determine U.S. participation, and confer federal privileges, exemptions, and immunities without a distinct congressional participation decision or clear accountability safeguards."}},{"id":"HOR-044","title":"Statutory Framework for Presidential Cross-Border Infrastructure Permits","issue_url":"https://github.com/Thorncrag/ARRP/issues/306","workflow_status":"Development","horizon_history":{"original_concern":"Cross-border pipelines, railways, bridges, and comparable facilities may be approved through a presidential permitting system created substantially by executive practice without uniform statutory criteria or procedures, and some decisions may fall outside ordinary APA review."}},{"id":"HOR-045","title":"Immigration-Enforcement Vehicle-Stop Safeguards","issue_url":"https://github.com/Thorncrag/ARRP/issues/311","workflow_status":"Deferred","horizon_history":{"original_concern":"Immigration-enforcement vehicle stops may lack sufficiently durable and measurable safeguards for particularized suspicion, target verification, documentation, signaling, de-escalation, and public reporting."}}],
